-- Cloudflare D1 Migration: Real Exam Recall & Forecast Engine
-- Writing Recalls, Reading CBT Recalls, and Live Exam Lexicons

CREATE TABLE IF NOT EXISTS exam_recalls_writing (
  id TEXT PRIMARY KEY,
  exam_date TEXT NOT NULL,
  test_type TEXT NOT NULL DEFAULT 'ACADEMIC',
  task_type TEXT NOT NULL,
  topic_category TEXT NOT NULL,
  title TEXT NOT NULL,
  prompt TEXT NOT NULL,
  model_essay TEXT NOT NULL,
  band_score REAL DEFAULT 8.5,
  lexical_highlights TEXT DEFAULT '[]',
  examiner_notes TEXT,
  is_free_sample INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS exam_recalls_reading (
  id TEXT PRIMARY KEY,
  exam_date TEXT NOT NULL,
  test_type TEXT NOT NULL DEFAULT 'ACADEMIC',
  passage_number INTEGER NOT NULL,
  title TEXT NOT NULL,
  category TEXT NOT NULL,
  difficulty TEXT NOT NULL,
  question_types TEXT NOT NULL,
  paragraphs_json TEXT NOT NULL,
  questions_json TEXT NOT NULL,
  is_free_sample INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS exam_recalls_lexicon (
  id TEXT PRIMARY KEY,
  word TEXT NOT NULL,
  phonetic TEXT,
  pos TEXT NOT NULL,
  band_tier TEXT DEFAULT 'Band 8.0 - 9.0',
  topic_category TEXT NOT NULL,
  definition_en TEXT NOT NULL,
  definition_mm TEXT NOT NULL,
  source_test_ref TEXT NOT NULL,
  real_exam_sentence TEXT NOT NULL,
  collocations_json TEXT DEFAULT '[]',
  paraphrase_json TEXT DEFAULT '{}',
  trap_notes TEXT,
  is_free_sample INTEGER DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_writing_date ON exam_recalls_writing(exam_date DESC);
CREATE INDEX IF NOT EXISTS idx_reading_date ON exam_recalls_reading(exam_date DESC);
CREATE INDEX IF NOT EXISTS idx_lexicon_date ON exam_recalls_lexicon(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_lexicon_free ON exam_recalls_lexicon(is_free_sample);

