INSERT OR REPLACE INTO exam_recalls_writing (id, exam_date, test_type, task_type, topic_category, title, prompt, model_essay, band_score, lexical_highlights, examiner_notes, is_free_sample, created_at) VALUES
(
  'REC-2026-W2-1539',
  '2026-10-24',
  'ACADEMIC',
  'TASK_2',
  'Culture & Globalization',
  'Global Fashion Trends & Cultural Heritage',
  'In many parts of the world, people''s choice of clothing is increasingly influenced by global fashion trends rather than traditional attire. To what extent do you agree or disagree with this development?',
  'In contemporary society, sartorial choices across metropolitan centers have converged remarkably around multinational apparel brands, overshadowing indigenous and traditional vestments. While some lament this cultural homogenization as a threat to ancestral identity, I firmly believe that this global evolution represents an inevitable and largely advantageous triumph of practical utility, personal autonomy, and cross-cultural democratization.\n\nFirst and foremost, the predominance of standardized modern fashion is underpinned by ergonomic functionality and economic accessibility. Traditional garments—such as the Japanese kimono, Indian saree, or Myanmar longyi—though aesthetically exquisite and deeply revered, frequently require elaborate maintenance and restrict rigorous physical mobility in industrial or corporate workspaces. In contrast, mass-manufactured contemporary garments are tailored with breathable textiles, reinforced stitching, and standardized sizing optimized for active daily transit. Furthermore, international economies of scale render everyday apparel remarkably affordable for lower- and middle-class demographics, democratizing style rather than confining elegance to affluent strata who can afford bespoke artisanal hand-weaving.\n\nSecondly, the transition towards transnational styles does not inherently signify the total extinction of ethnic heritage; rather, it cultivates sophisticated syncretism. Forward-thinking local designers consistently amalgamate ancestral motifs, organic botanical dyes, and hand-loomed brocades into modern tailored silhouettes. Consequently, young generations embrace their heritage with renewed vitality on ceremonial occasions and digital platforms, while adopting pragmatic westernized casualwear for routine occupations.\n\nIn conclusion, rather than a catastrophic erosion of native culture, the global convergence of fashion constitutes a pragmatic synthesis that harmonizes functional necessity with expressive individual liberty.',
  8.5,
  '["sartorial choices", "cultural homogenization", "indigenous vestments", "ergonomic functionality", "sophisticated syncretism", "bespoke artisanal"]',
  'Band 8.5 criteria breakdown: Coherence and Cohesion exhibits seamless topical flow with paragraph-level thematic progression. Lexical Resource demonstrates sophisticated idiomatic command (sartorial, syncretism, amalgamate) with zero mechanical strain.',
  1,
  1793160000000
),
(
  'REC-2026-W2-1540',
  '2026-10-18',
  'ACADEMIC',
  'TASK_2',
  'Technology & Workforce',
  'Generative AI Automation in Professional Professions',
  'Some experts argue that the rapid rise of artificial intelligence will eliminate millions of white-collar cognitive jobs, while others maintain that it will create more creative and supervisory roles. Discuss both views and give your own opinion.',
  'The proliferation of sophisticated artificial intelligence systems and autonomous generative algorithms has ignited vigorous international debate regarding the destiny of human intellectual labor. While one faction cautions that widespread algorithmic displacement poses an existential crisis to routine professional employment, others contend that cognitive automation will liberate human talent for elevated conceptual governance. In my evaluation, while transitional displacement is unavoidable for perfunctory clerical positions, AI ultimately serves as an intellectual catalyst that augments human strategic ingenuity.\n\nOn the one hand, apprehensions concerning large-scale technological obsolescence are far from unsubstantiated. Modern transformer architectures and neural networks excel at parsing gargantuan legal precedents, synthesizing medical radiology diagnostics, and authoring boilerplate computational code at velocities unattainable by human practitioners. Consequently, entry-level analytical professions—such as paralegals, financial risk assessors, and standard copywriters—face imminent structural contraction as enterprise corporations automate procedural tasks to slash operational overhead.\n\nOn the other hand, technological history consistently demonstrates that systemic automation shifts the frontier of human productivity rather than eradicating the demand for labor. As algorithmic tools absorb repetitive synthesis, human professionals are elevated into indispensable evaluative arbiters. Clinical medicine, ethical jurisprudence, and institutional architecture necessitate qualitative empathy, contextual discernment, and moral accountability—facets fundamentally alien to mathematical probabilistic models.\n\nTo conclude, while structural upheaval warrants proactive pedagogical recalibration, artificial intelligence will fundamentally augment rather than extinguish skilled human enterprise.',
  9.0,
  '["algorithmic displacement", "cognitive automation", "paragantuan legal precedents", "evaluative arbiters", "contextual discernment", "pedagogical recalibration"]',
  'Band 9.0 criteria breakdown: Flawless task achievement with balanced nuanced reasoning; exceptional sophistication of collocations and seamless discourse cohesion.',
  1,
  1793150000000
),
(
  'REC-2026-W1-420',
  '2026-10-11',
  'ACADEMIC',
  'TASK_1',
  'Renewable Energy Transitions',
  'Comparative Electricity Production by Fuel Source (2015-2025)',
  'The chart below illustrates the proportion of electricity generated from renewable sources, fossil fuels, and nuclear power across four European economies between 2015 and 2025. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.',
  'The stacked bar chart delineates the proportional contributions of fossil fuels, renewable alternatives, and nuclear energy toward total domestic electricity generation across four designated European nations over a ten-year timeframe spanning from 2015 to 2025.\n\nOverall, the decadal progression was characterized by a pronounced structural transition away from hydrocarbon dependence in favor of clean renewables across all surveyed territories. Germany and the United Kingdom spearheaded this transformation, while France consistently maintained its distinctive reliance on nuclear fission as its predominant energy pillar.\n\nIn 2015, fossil fuels constituted the prevailing source of power generation, commanding 58% in the UK and 52% in Germany. Over the ensuing decade, however, both nations enacted sweeping grid decarbonization policies. Consequently, by 2025, renewable energy sources—predominantly offshore wind and photovoltaic arrays—surged to 54% in the UK and 61% in Germany, while the fossil fuel share plummeted to 24% and 27% respectively.\n\nConversely, France exhibited a remarkably stable generation profile. Nuclear energy consistently contributed between 68% and 72% across the entire period, leaving renewables to expand incrementally from 14% to 22%, chiefly at the expense of residual coal and gas output.',
  8.5,
  '["spearheaded this transformation", "hydrocarbon dependence", "grid decarbonization", "photovoltaic arrays", "generation profile"]',
  'Band 8.5 Task 1: Clear holistic overview paragraph with key trends highlighted; precise numerical comparisons; excellent technical terminology.',
  1,
  1793140000000
),
(
  'REC-2026-W2-1541',
  '2026-09-28',
  'ACADEMIC',
  'TASK_2',
  'Urban Planning & Housing',
  'Compulsory Relocation of Heavy Industrial Facilities from Megacities',
  'Municipal authorities should mandate the complete relocation of manufacturing factories and heavy industries away from capital cities into remote rural zones. To what extent do you agree or disagree?',
  'The relentless expansion of metropolitan conurbations has prompted intense scrutiny regarding the spatial coexistence of heavy industrial complexes alongside dense residential communities. While relocating noxious factories to peripheral hinterlands significantly mitigates urban air pollution and alleviates vehicular gridlock, I contend that an unconditional compulsory exodus risks destabilizing municipal supply chains and inflicting severe environmental degradation on pristine rural ecosystems.\n\nAdvocates of industrial zoning outside major capitals cite compelling public health and spatial arguments. Heavy metallurgical refineries and chemical synthesizers emit airborne particulate matter (PM2.5) and industrial effluent that grievously exacerbate respiratory pathologies among urban inhabitants. Evacuating these facilities beyond commuter belts immediately ameliorates ambient air quality and liberates expansive land tracts for affordable housing and urban green corridors.\n\nNevertheless, an absolute relocation mandate overlooks severe logistical and socio-ecological repercussions. Transporting finished merchandise back to urban consumer nodes substantially amplifies heavy freight emissions, counteracting the net ecological gains. Furthermore, industrializing fragile rural regions risks contaminating agrarian watersheds and destabilizing biodiversity.',
  8.5,
  '["spatial coexistence", "noxious factories", "peripheral hinterlands", "industrial effluent", "ambient air quality", "agrarian watersheds"]',
  'VIP Exclusive Essay: Band 8.5 balanced thesis with advanced spatial economics vocabulary.',
  0,
  1793130000000
),
(
  'REC-2026-W2-1542',
  '2026-09-14',
  'ACADEMIC',
  'TASK_2',
  'Education & Assessment',
  'Standardized Testing vs Continuous Formative Assessment',
  'Many educational systems rely predominantly on high-stakes terminal examinations to rank student ability, whereas others favor continuous project-based evaluation. Discuss both approaches and give your opinion.',
  'The mechanism by which scholastic competence is evaluated remains a contentious cornerstone of educational reform. While terminal summative examinations offer uniform, objective, and fraud-resistant benchmarking, I firmly concur with the view that continuous formative evaluation yields a profoundly more holistic and authentic appraisal of practical capability and intellectual resilience.\n\nTerminal examinations undeniably provide administrative equity and standardized rigor. Administering an identical assessment simultaneously under invigilated conditions minimizes institutional bias, nepotism, and subjectivity, ensuring an egalitarian playing field for competitive university matriculation.\n\nHowever, high-stakes terminal testing frequently induces catastrophic psychological anxiety, incentivizing pedagogical cramming rather than profound conceptual assimilation. In stark contrast, continuous formative assessment mirrors real-world professional collaboration through iterative research projects, verbal defenses, and experiential portfolio creation.',
  8.5,
  '["summative examinations", "formative evaluation", "pedagogical cramming", "invigilated conditions", "egalitarian playing field", "conceptual assimilation"]',
  'VIP Exclusive Essay: Band 8.5 with detailed pedagogical discourse.',
  0,
  1793120000000
);

